 static Definition get(String id){return ALL.get(id);}
 static int limited(String id,int level){var d=get(id);return Math.max(0,Math.min(d==null?5:d.maximum(),level));}
 static boolean canInfuse(int current,int added,int maximum){return current>=0&&added>0&&current<maximum&&(long)current+added<=maximum;}
 static int upgradedLevel(String id,List<Integer> levels){var d=get(id);if(d==null||d.group()!=RareCompatibility.Group.OTHER||levels.size()<2)return 0;long total=0;for(int level:levels){if(level<=0||level>d.maximum())return 0;total+=level;}return total<=d.maximum()?(int)total:0;}
 static double fallMultiplier(int level){return Math.max(0,1-.25*Math.max(0,Math.min(4,level)));}
 static double executeThreshold(int level){return .05+.05*Math.max(1,Math.min(4,level));}
 static int repairAmount(int maximum,int level){return Math.max(1,(int)Math.ceil(maximum*.2*Math.max(1,Math.min(5,level))));}
 static int clarityTicks(int ticks,int level){return Math.max(1,(int)Math.ceil(ticks*(1-.25*Math.max(0,Math.min(3,level)))));}
